<script setup lang="ts">
import Pagination from '../../shared/components/Pagination.vue'
import { onBeforeUnmount,onMounted,ref } from 'vue'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import { useWorkspace } from '../../app/workspace'
const { caseTotal, page, intelligence, can,api } = useWorkspace()
const modelTotal=ref<number|null>(null),requests=createLatestRequests(api)
onBeforeUnmount(()=>requests.dispose())
onMounted(async()=>{if(can('models.read')){try{const result=await requests.latest<{total:number}>('model-total','/analysis/models/search',{method:'POST',body:JSON.stringify({page:1})});modelTotal.value=result.total}catch(e){if(!isCancelled(e))modelTotal.value=null}}})
const { myPage,reviewPage,myTasks, myTotal, mineLoading, mineError, loadMine, reviewTasks, reviewTotal, reviewLoading, reviewError, loadReviewQueue } = intelligence
const taskStatus: Record<string,string> = {OPEN:'待办理',RETURNED:'已退回',PENDING_REVIEW:'待复核',CLOSED:'已关闭'}
onMounted(() => { if(can('intelligence.read')){void loadMine(); void loadReviewQueue()} })
</script>

<template>
<div class="metrics"><div v-if="can('cases.read')" class="card"><span>案件草稿</span><strong>{{caseTotal}}</strong><small>当前查询结果总数</small></div><div v-if="can('models.read')" class="card"><span>业务模型</span><strong>{{modelTotal??'—'}}</strong><small>{{modelTotal===null?'模型统计暂不可用':'当前组织登记模型总数'}}</small></div></div><section v-if="can('intelligence.read')" class="card intro"><h2>我的核查工单</h2><p class="muted">当前登录人承办且未关闭的工单，按办理期限排序；每页显示 5 条，打开情报线索可查看详情。</p><p v-if="mineLoading" role="status">正在加载待办…</p><p v-else-if="mineError" class="error" role="alert">{{mineError}} <button class="link" @click="loadMine()">重试</button></p><p v-else-if="!myTasks.length" class="empty">暂无待办</p><div v-else class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>线索</th><th>工单状态</th><th>办理期限</th></tr></thead><tbody><tr v-for="(task, rowIndex) in myTasks" :key="task.id"><td class="row-number">{{(myPage-1)*5+rowIndex+1}}</td><td>{{task.clue_title}}</td><td>{{taskStatus[task.status] || '未知状态'}}</td><td>{{task.due_date || '未设置'}}</td></tr></tbody></table><p class="muted">共 {{myTotal}} 条；列表仅含当前组织且当前账号承办的工单。</p></div><Pagination :page="myPage" :total="myTotal" :page-size="5" :loading="mineLoading" @change="loadMine($event)" /><button class="secondary" @click="page='情报线索'">进入情报线索</button></section><section v-if="can('intelligence.read')" class="card intro"><h2>待我复核</h2><p class="muted">本组织中由其他用户提交、处于待复核状态的工单；每页显示 5 条，正式岗位授权尚未实现。</p><p v-if="reviewLoading" role="status">正在加载…</p><p v-else-if="reviewError" class="error" role="alert">{{reviewError}} <button class="link" @click="loadReviewQueue()">重试</button></p><p v-else-if="!reviewTasks.length" class="empty">暂无待复核工单</p><div v-else class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th>线索</th><th>状态</th></tr></thead><tbody><tr v-for="(task, rowIndex) in reviewTasks" :key="task.id"><td class="row-number">{{(reviewPage-1)*5+rowIndex+1}}</td><td>{{task.clue_title}}</td><td>待复核</td></tr></tbody></table><p class="muted">共 {{reviewTotal}} 条；进入情报线索后查看详情。</p></div><Pagination :page="reviewPage" :total="reviewTotal" :page-size="5" :loading="reviewLoading" @change="loadReviewQueue($event)" /><button class="secondary" @click="page='情报线索'">进入情报线索</button></section><div class="card intro"><h2>开始使用</h2><p>可从接警信息转办或直接创建案件草稿，维护建模项目、业务分析模型和技战法资料。</p><div class="actions"><button v-if="can('cases.read')" @click="page='案件管理'">进入案件管理</button><button v-if="can('modeling.read')" class="secondary" @click="page='分析建模'">进入分析建模</button></div><p class="muted">人员身份核验、正式审批和独立受保护审计仍待建设；AI 草稿须人工核验。</p></div>
</template>
